import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSurinsarMansarData(){const e=readFileSync(resolve(__dirname,"../../frontend/surinsar-mansar-lakes-explorer/surinsar-mansar-data.js"),"utf-8");return new Function(e+"\nreturn { SM_INFO, TWIN_LAKE_ECOSYSTEM, RAMSAR_DETAILS, RELIGIOUS_IMPORTANCE, WILDLIFE_SPECIES, BIRD_SPECIES, LOCAL_LEGENDS, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Surinsar-Mansar Lakes Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadSurinsarMansarData()}),describe("SM_INFO metadata",()=>{it("contains correct wetland metadata and Ramsar status",()=>{expect(e.SM_INFO.id).toBe("surinsar-mansar-lakes"),expect(e.SM_INFO.name).toBe("Surinsar-Mansar Lakes"),expect(e.SM_INFO.ramsarYear).toBe(2005),expect(e.SM_INFO.ramsarSiteNo).toBe(1573),expect(e.SM_INFO.state).toBe("Jammu & Kashmir")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SM_INFO.quickStats)).toBe(!0),expect(e.SM_INFO.quickStats.length).toBe(6)})}),describe("TWIN_LAKE_ECOSYSTEM",()=>{it("covers both lakes and hydrology",()=>{expect(e.TWIN_LAKE_ECOSYSTEM.overview).toBeDefined(),expect(e.TWIN_LAKE_ECOSYSTEM.surinsarProfile).toContain("Surinsar"),expect(e.TWIN_LAKE_ECOSYSTEM.mansarProfile).toContain("Mansar"),expect(e.TWIN_LAKE_ECOSYSTEM.hydrology).toBeDefined()})}),describe("RAMSAR_DETAILS",()=>{it("documents criteria and threats",()=>{expect(e.RAMSAR_DETAILS.summary).toContain("8 November 2005"),expect(Array.isArray(e.RAMSAR_DETAILS.criteria)).toBe(!0),expect(e.RAMSAR_DETAILS.criteria.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.RAMSAR_DETAILS.threats)).toBe(!0),expect(e.RAMSAR_DETAILS.conservation).toBeDefined()})}),describe("Species catalogs",()=>{it("wildlife covers the CITES-listed turtles and the medusa",()=>{const t=e.WILDLIFE_SPECIES.find(e=>"indian-flapshell-turtle"===e.id),a=e.WILDLIFE_SPECIES.find(e=>"indian-softshell-turtle"===e.id),r=e.WILDLIFE_SPECIES.find(e=>"mansariella-medusa"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(r).toBeDefined()}),it("birdlife includes the key wintering waterfowl",()=>{const t=e.BIRD_SPECIES.find(e=>"common-coot"===e.id),a=e.BIRD_SPECIES.find(e=>"common-pochard"===e.id),r=e.BIRD_SPECIES.find(e=>"tufted-duck"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(r).toBeDefined()})}),describe("Mythology, map hotspots and gallery",()=>{it("includes local legends",()=>{expect(Array.isArray(e.LOCAL_LEGENDS)).toBe(!0),expect(e.LOCAL_LEGENDS.length).toBeGreaterThanOrEqual(3)}),it("has map hotspots and gallery images",()=>{expect(Array.isArray(e.MAP_HOTSPOTS)).toBe(!0),expect(e.MAP_HOTSPOTS.length).toBeGreaterThanOrEqual(3),expect(e.MAP_HOTSPOTS.find(e=>"mansar-lake"===e.id)).toBeDefined(),expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(4)})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"surinsar-mansar-lakes"===e.id);expect(e).toBeDefined(),expect(e.ramsarSiteNo).toBe(1573),expect(e.state).toBe("Jammu & Kashmir"),expect(e.exploreUrl).toBe("../surinsar-mansar-lakes-explorer/index.html")})})});